/* Execute unmodified stock WriteChunks on generated bytes in an isolated
 * namespace. This is file I/O evidence, not camera output or a saved photo. */
extern int printf(const char *, ...), snprintf(char *, unsigned int, const char *, ...);
extern void *dlopen(const char *, int), *dlsym(void *, const char *);
extern void *fopen(const char *, const char *);
extern unsigned int fread(void *, unsigned int, unsigned int, void *), fwrite(const void *, unsigned int, unsigned int, void *);
extern int fclose(void *), access(const char *, int), *__errno_location(void);
#define CHECK(x) do { if (!(x)) { printf("FAIL line=%d errno=%d\n", __LINE__, *__errno_location()); return 1; } } while (0)
typedef unsigned int u32;
static u32 object[0x78/4], image[0x30/4], descriptor[0x50/4], chunks[4];
static const char first[] = "generated-", second[] = "save-proof\n";
static int copy_file(const char *source, const char *target) {
    void *input = fopen(source, "rb");
    if (!input) return 0;
    void *output = fopen(target, "wb");
    if (!output) { fclose(input); return 0; }
    char bytes[4096]; unsigned int count;
    while ((count = fread(bytes, 1, sizeof bytes, input)))
        if (fwrite(bytes, 1, count, output) != count) { fclose(input); fclose(output); return 0; }
    fclose(input);
    return fclose(output) == 0;
}
int main(int argc, char **argv) {
    CHECK(argc == 2);
    CHECK(dlopen("libsif.so", 2|0x100));
    unsigned int (*write_chunks)(void *) = dlsym((void *)0, "_ZN14DscFileHandler11WriteChunksEv");
    const char *(*directory)(void) = dlsym((void *)0, "nx_capture_observer_directory");
    CHECK(write_chunks && directory);
    object[0x64/4] = (u32)image; image[0x2c/4] = (u32)descriptor;
    chunks[0] = (u32)first; chunks[1] = sizeof first-1;
    chunks[2] = (u32)second; chunks[3] = sizeof second-1;
    descriptor[0] = (u32)chunks; descriptor[1] = descriptor[2] = (u32)(chunks+4);
    const char *names[3] = {"normal", "stop", "full"};
    const char *paths[3] = {"/var/run/capture-save-generated.bin", "/var/run/capture-save-stopped.bin", "/dev/full"};
    for (int i = 0; i < 3; ++i) {
        snprintf((char *)descriptor+12, 52, "%s", paths[i]);
        object[0x70/4] = i == 1 ? 2 : 0;
        unsigned int result = write_chunks(object);
        CHECK(result == 1); // Stock also returns true after a failed Close flush.
        if (i == 1) CHECK(access(paths[i], 0) == -1);
        if (i == 0) {
            char actual[64];
            void *file = fopen(paths[i], "rb"); CHECK(file);
            unsigned int count = fread(actual, 1, sizeof actual, file); fclose(file);
            CHECK(count == sizeof first+sizeof second-2);
            for (unsigned int j = 0; j < sizeof first-1; ++j) CHECK(actual[j] == first[j]);
            for (unsigned int j = 0; j < sizeof second-1; ++j) CHECK(actual[sizeof first-1+j] == second[j]);
        }
        char source[256], target[512];
        snprintf(source, sizeof source, "%s/event-%u.json", directory(), (u32)i+1);
        snprintf(target, sizeof target, "%s/%s.json", argv[1], names[i]);
        CHECK(copy_file(source, target));
        if (i == 0) {
            snprintf(target, sizeof target, "%s/generated.bin", argv[1]);
            CHECK(copy_file(paths[i], target));
        }
        printf("SAVE_IO case=%s original_result=%u generated_bytes=%u photo_completion_proven=0\n",
               names[i], result, (u32)(sizeof first+sizeof second-2));
    }
    return 0;
}
